    'course.welcome.title': 'Velkomen til Dataspatium',
    'course.welcome.p1': 'Dataspatium hentar, bearbeider, analyserer, visualiserer og eksporterer data heilt i nettlesaren. Ingenting blir installert, og dataa dine forlèt ikkje datamaskina med mindre du sjølv hentar frå eit API.',
    'course.welcome.p2': 'Grunnkurset tek om lag ti minutt. Du følgjer eit konkret døme, {example}, gjennom dei åtte modusane i appen: {modes}. I kvart steg kan du gjere oppgåva sjølv eller la kurset gjere henne for deg.',
    'course.welcome.p3': 'Skjermen ser lik ut i alle modusar: modusane øvst, objektpanelet til venstre, arbeidsflata i midten, eigenskapane til høgre og loggen nedst. Kurset kan minimerast og opnast igjen frå hjelpa.',
    'course.import.title': 'Hent: hent data',
    'course.import.p1': 'Alle data i appen ligg i datasett: tabellar med namngjevne kolonnar, der kvar kolonne har ein type som tekst, heiltal, tal eller dato. Data kan hentast frå filer (CSV, Excel, JSON, Parquet, SPSS med fleire), innlimt tekst, nettadresser og opne API-ar frå etatar i heile Norden.',
    'course.import.task': 'Gå til {mode} og klikk på {button}. Då blir datasettet {name} oppretta.',
    'course.import.done': 'Datasettet er oppretta: 290 svenske kommunar med kolonnane kommunkod (kommunekode), kommun (kommune), lanskod (länskode), lan (län), ar (år) og folkmangd (folketal). Kortnamnet er {short}.',
    'course.manage.title': 'Handter: datasett og arbeidsområdet',
    'course.manage.p1': 'Kvart datasett har eit namn og eit kortnamn. Kortnamnet, her {short}, har berre små bokstavar, siffer og understrekar og blir brukt i SQL og R. I {mode} ser du kjelda, storleiken, kolonnane med typar og skildringar og versjonar som du kan gå tilbake til.',
    'course.manage.p2': 'Alt blir lagra automatisk i nettlesaren. Ta ein tryggingskopi av arbeidsområdet av og til med {backup}, slik at ingenting går tapt om dataa i nettlesaren blir sletta.',
    'course.manage.task': 'Opne {mode}, vel datasettet i objektpanelet og sjå på opplysningane og kolonnane.',
    'course.manage.done': 'Her kan du òg endre namn og kortnamn, dele datasett som pakkar og slette dei.',
    'course.process.title': 'Bearbeid: reins og rekn ut',
    'course.process.p1': 'I {mode} ser du heile tabellen. Klikk på ei kolonneoverskrift for å sortere og sjå profilen til kolonnen med manglande verdiar, unike verdiar og fordeling. Rett verdiar direkte i cellene eller med handlingar.',
    'course.process.p2': 'Kvar endring blir eit steg i {recipe} til datasettet. Stega kan angrast, køyrast på nytt på ein ny versjon av dataa og kopierast som R- eller SQL-kode.',
    'course.process.task': 'Lag ein kolonne med folketalet i tusen: {mode} → {actions} → {group} → {op}. Oppgje namnet {column} og uttrykket {expression}.',
    'course.process.done': 'Kolonnen {column} ligg no sist i tabellen, og steget står i oppskrifta.',
    'course.sql.title': 'Analyser: spør med SQL',
    'course.sql.p1': '{mode} er modusen for kode og statistikk. I SQL-fana heiter det valde datasettet {data}, men alle datasett kan òg nåast med kortnamna sine. Difor kan éi spørjing kople saman fleire datasett.',
    'course.sql.task': 'Opne {mode} → {tab}, skriv spørjinga nedanfor og klikk på {run}. Spørjinga summerer folketalet per län.',
    'course.sql.done': 'Stockholms län er størst med nesten 2,5 millionar innbyggjarar, følgt av Västra Götalands og Skåne län. Med {save} blir resultatet eit nytt datasett.',
    'course.r.title': 'Analyser: rekn med R',
    'course.r.p1': 'R-fana køyrer R direkte i nettlesaren med pakkar som dplyr og ggplot2. {read} les eit datasett som ein data frame, og {write} lagrar ein data frame som eit nytt datasett. Første gongen tek det nokre sekund å starte R.',
    'course.r.task': 'Opne {mode} → {tab}, skriv koden nedanfor og klikk på {run}. Koden summerer opp folketalet og teiknar eit histogram.',
    'course.r.done': 'Medianen er drygt 16 000 innbyggjarar: halvparten av kommunane er mindre enn det, og den største, Stockholm, har nesten ein million. Difor har diagrammet ein logaritmisk skala.',
    'course.viz.title': 'Visualiser: lag eit diagram',
    'course.viz.p1': 'Diagram blir laga med diagrambyggjaren (Vega-Lite), ferdige D3-malar eller R. Alle brukar fargane og skrifttypane til appen, blir teikna på nytt når dataa endrar seg, og kan samlast i dashbord med felles filter.',
    'course.viz.task': 'Opne {mode} → {new} → {builder}. Vel {type}, set {x} til lan ({y} er allereie folkmangd) og klikk på {save}.',
    'course.viz.done': 'Diagrammet er lagra. Prøv òg diagramtypen {map} saman med dømedatasettet {boundaries} for å vise folketalet på eit kart.',
    'course.export.title': 'Eksporter: del resultatet',
    'course.export.p1': 'I {mode} lagrar du data som CSV, Excel, JSON, Parquet, SQLite, SPSS og fleire format, diagram som PNG, SVG, PDF eller PowerPoint og dokument frå malar som Word, PDF, HTML eller LaTeX, òg eitt dokument per gruppe i éi køyring.',
    'course.export.task': 'Opne {mode}, vel til dømes formatet Excel og klikk på {run}.',
    'course.export.done': 'Fila hamnar blant nedlastingane i nettlesaren. Fanene {charts} og {documents} fungerer på same måte for diagram og dokument.',
    'course.finish.title': 'Ferdig: slik går du vidare',
    'course.finish.p1': 'Du har gått gjennom heile kjeda: hente, handtere, bearbeide, analysere, visualisere og eksportere.',
    'course.finish.p2': 'Hald fram med eigne data: slepp ei fil i {import}, vel land og hent frå eit ope API, skriv notatbøker med tekst, R og SQL i {analyse} eller lag dokumentmalar i {export}. Alt+1–6 byter modus, og {palette} opnar kommandopaletten.',
    'course.finish.p3': 'Kurset er framleis tilgjengeleg under {help} og i kommandopaletten.',
